120	.category-items {
121	  display: flex;
122	  flex-wrap: wrap;
123	  gap: 8px;
124	}
125	
126	@media (max-width: 768px) {
127	  .category-items {
128	    display: none;
129	  }
130	
131	  .category.expanded .category-items {
132	    display: flex;
133	    flex-direction: column;
134	    padding: 12px;
135	    background: var(--bg-secondary);
136	    border-radius: 8px;
137	  }
138	}
139	```
140	
141	---
142	
143	## Form Layouts
144	
145	### Problem
146	Multi-column form layouts get cut off on mobile.
147	
148	### Solution
149	Stack vertically with full width.
150	
151	```css
152	.form-row {
153	  display: flex;
154	  gap: 16px;
155	}
156	
157	.form-group {
158	  flex: 1;
159	}
160	
161	@media (max-width: 768px) {
162	  .form-row {
163	    flex-direction: column;
164	  }
165	
166	  .form-group {
167	    width: 100%;
168	  }
169	  
170	  .form-row.half-width {
171	    /* Even "half width" fields go full on mobile */
172	    flex-direction: column;
173	  }
174	}
175	```
176	
177	---
178	
179	## Status/Alert Cards
180	
181	### Problem
182	Inconsistent text alignment when stacking horizontal elements vertically.
183	
184	### Solution
185	Both `align-items: center` AND `text-align: center`.
186	
187	```css
188	.alert {
189	  display: flex;
190	  align-items: flex-start;
191	  gap: 12px;
192	  padding: 16px;
193	  border-radius: 8px;
194	}
195	
196	.alert-icon {
197	  flex-shrink: 0;
198	}
199	
200	.alert-content {
201	  flex: 1;
202	}
203	
204	@media (max-width: 768px) {
205	  .alert {
206	    flex-direction: column;
207	    align-items: center;  /* Center flex items */
208	    text-align: center;   /* Center text within items */
209	    gap: 8px;
210	  }
211	
212	  .alert-content {
213	    text-align: center;  /* Explicit for nested elements */
214	  }
215	
216	  .alert strong {
217	    text-align: center;  /* Block elements need explicit */
218	  }
219	}
220	```
221	
222	**Key Rule**: Stacked flex items need BOTH `align-items: center` AND `text-align: center`.
223	
224	---
225	
226	## Grid Layouts
227	
228	### Universal Mobile Collapse
229	
230	```css
231	.pricing-grid,
232	.feature-grid,
233	.team-grid,
234	.stats-grid,
235	.testimonial-grid {
236	  display: grid;
237	  gap: 24px;
238	}
239	
240	/* Desktop configurations */
241	.pricing-grid { grid-template-columns: repeat(3, 1fr); }
242	.feature-grid { grid-template-columns: repeat(3, 1fr); }
243	.team-grid { grid-template-columns: repeat(4, 1fr); }
244	.stats-grid { grid-template-columns: repeat(4, 1fr); }
245	.testimonial-grid { grid-template-columns: repeat(2, 1fr); }
246	
247	/* Tablet */
248	@media (max-width: 1024px) {
249	  .team-grid { grid-template-columns: repeat(2, 1fr); }
250	  .stats-grid { grid-template-columns: repeat(2, 1fr); }
251	}
252	
253	/* Mobile: Everything single column */
254	@media (max-width: 768px) {
255	  .pricing-grid,
256	  .feature-grid,
257	  .team-grid,
258	  .stats-grid,
259	  .testimonial-grid {
260	    grid-template-columns: 1fr;
261	  }
262	}
263	```
264	
265	---
266	
267	## Navigation
268	
269	### Mobile Menu Pattern
270	
271	```tsx
272	function MobileNav() {
273	  const [open, setOpen] = useState(false);
274	
275	  return (
276	    <>
277	      {/* Mobile menu button */}
278	      <button 
279	        className="md:hidden"
280	        onClick={() => setOpen(!open)}
281	      >
282	        {open ? <X /> : <Menu />}
283	      </button>
284	
285	      {/* Mobile menu overlay */}
286	      <div className={cn(
287	        "fixed inset-0 bg-black/50 md:hidden transition-opacity",
288	        open ? "opacity-100" : "opacity-0 pointer-events-none"
289	      )} onClick={() => setOpen(false)} />
290	
291	      {/* Mobile menu panel */}
292	      <nav className={cn(
