296	      )}>
297	        {/* Nav items */}
298	      </nav>
299	    </>
300	  );
301	}
302	```
303	
304	---
305	
306	## Form Element Consistency
307	
308	### Always Style as a Group
309	
310	```css
311	/* WRONG - Only targets input */
312	.input {
313	  border: 2px solid var(--border);
314	  border-radius: 8px;
315	}
316	
317	/* CORRECT - All form fields */
318	.input,
319	.select,
320	.textarea {
321	  border: 2px solid var(--border);
322	  border-radius: 8px;
323	  padding: 12px 16px;
324	  font-size: 16px; /* Prevents iOS zoom */
325	  background: var(--bg-secondary);
326	  color: var(--text-primary);
327	}
328	```
329	
330	### Textarea Border Radius Exception
331	
332	Pill-shaped inputs look wrong on textareas:
333	
334	```css
335	.input,
336	.select {
337	  border-radius: 100px; /* Pill shape */
338	}
339	
340	.textarea {
341	  border-radius: 16px; /* Softer, but not pill */
342	}
343	```
344	
345	### Dropdown Option Styling
346	
347	`<option>` elements can't inherit backdrop-filter:
348	
349	```css
350	.select {
351	  background: rgba(255, 255, 255, 0.1);
352	  backdrop-filter: blur(10px);
353	  color: white;
354	}
355	
356	/* Options need solid backgrounds */
357	.select option {
358	  background: #1a1a2e;
359	  color: white;
360	}
361	```
362	
363	### Prevent iOS Zoom on Focus
364	
365	iOS zooms on inputs with font-size < 16px:
366	
367	```css
368	input, select, textarea {
369	  font-size: 16px; /* Minimum to prevent zoom */
370	}
371	
372	/* Or use transform trick */
373	@media (max-width: 768px) {
374	  input, select, textarea {
375	    font-size: 16px;
376	  }
377	}
378	```
379	
380	---
381	
382	## Color Contrast Checklist
383	
384	### Badge/Pill Elements
385	
386	```css
387	/* WRONG - May be invisible */
388	.badge {
389	  background: var(--accent);
390	  color: white; /* Might not contrast */
391	}
392	
393	/* CORRECT - Ensure contrast */
394	.badge {
395	  background: var(--accent);
396	  color: var(--accent-foreground); /* Defined to contrast */
397	}
398	```
399	
400	### Color Swatches
401	
402	Swatches showing colors need visible borders:
403	
404	```css
405	.color-swatch {
406	  border: 2px solid rgba(255, 255, 255, 0.15);
407	  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3);
408	}
409	```
410	
411	### Dark Theme Form Labels
412	
413	```css
414	/* WRONG - Hardcoded */
415	.label {
416	  color: white;
417	}
418	
419	/* CORRECT - Semantic variable */
420	.label {
421	  color: var(--text-primary);
422	}
423	```
