    .stat-item {
      text-align: center;
    }

    .stat-value {
      font-size: 28px;
      font-weight: 700;
      color: var(--accent);
      font-family: 'JetBrains Mono', monospace;
    }

    .stat-label {
      font-size: 13px;
      color: var(--text-secondary);
      margin-top: 4px;
    }

    /* Latest News */
    .latest-section {
      margin-bottom: 64px;
    }

    .latest-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .news-card {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 24px;
      transition: all 0.2s ease;
      cursor: pointer;
      display: flex;
      flex-direction: column;
    }

    .news-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .news-card .card-title {
      font-size: 17px;
    }

    .news-card .card-excerpt {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.6;
      flex: 1;
    }

    /* No Results */
    .no-results {
      display: none;
      text-align: center;
      padding: 64px 24px;
      background: var(--bg-secondary);
      border-radius: var(--radius-lg);
