      margin-bottom: 64px;
      position: relative;
      overflow: hidden;
    }

    .cta-section::before {
      content: '';
      position: absolute;
      top: 0;
      right: 0;
      width: 50%;
      height: 100%;
      background: radial-gradient(ellipse at right center, rgba(0, 114, 245, 0.15) 0%, transparent 70%);
      pointer-events: none;
