      background: var(--accent-hover);
    }

    .cta-section .btn-outline {
      color: white;
      border-color: rgba(255,255,255,0.2);
    }

    .cta-section .btn-outline:hover {
      border-color: white;
      background: rgba(255,255,255,0.1);
    }

