    }

    .footer-col a:hover {
      color: var(--text-primary);
    }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 24px;
      border-top: 1px solid var(--border);
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 600;
      font-size: 15px;
      color: var(--text-primary);
      text-decoration: none;
    }

    .footer-logo svg {
      width: 24px;
      height: 24px;
    }

    .status-badge {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      color: var(--text-secondary);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22C55E;
      border-radius: 50%;
    }

    .footer-links {
      display: flex;
      gap: 20px;
    }

    .footer-links a {
      font-size: 13px;
      color: var(--text-secondary);
      text-decoration: none;
    }

    .footer-links a:hover {
      color: var(--text-primary);
    }

    /* Animations */
    @keyframes fadeSlideUp {
      from {
        opacity: 0;
        transform: translateY(20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .animate-in {
      animation: fadeSlideUp 0.5s ease-out both;
    }

    .delay-1 { animation-delay: 0.1s; }
    .delay-2 { animation-delay: 0.2s; }
    .delay-3 { animation-delay: 0.3s; }
    .delay-4 { animation-delay: 0.4s; }
    .delay-5 { animation-delay: 0.5s; }

    /* Responsive */
    @media (max-width: 1024px) {
      .featured-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .featured-card-main {
        grid-column: span 2;
      }

      .latest-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: repeat(3, 1fr);
      }

      .dropdown {
        min-width: 400px;
      }
    }

    @media (max-width: 768px) {
      .nav,
      .header-actions .btn {
        display: none;
      }

      .mobile-menu-btn {
        display: block;
      }

      .hero {
        padding: 40px 0 32px;
      }

      .hero-title {
        font-size: 32px;
      }

      .hero-subtitle {
        font-size: 16px;
      }

      .filters-inner {
        flex-direction: column;
        align-items: stretch;
      }

      .filter-pills {
        overflow-x: auto;
        flex-wrap: nowrap;
        padding-bottom: 8px;
        -webkit-overflow-scrolling: touch;
      }

      .search-box {
        width: 100%;
      }

      .featured-grid {
        grid-template-columns: 1fr;
      }

      .featured-card-main {
        grid-column: span 1;
      }

      .latest-grid {
        grid-template-columns: 1fr;
      }

      .stats-bar {
        gap: 24px;
