      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .enterprise-cta {
        flex-direction: column;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .container {
        padding: 0 16px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }
